/*
  LazyGL : empêche tes effets WebGL de se lancer tous en même temps.

  Le problème : Chrome ne garde qu'un nombre limité de contextes WebGL en vie (environ 8 sur téléphone,
  16 sur ordinateur). Quand il y en a trop, il TUE les plus anciens : l'effet disparaît, et un canvas
  plein écran mort s'affiche en blanc avec un visage triste.

  La solution : cette enveloppe. Elle fait trois choses.
    1. Un effet n'est créé que quand sa section approche de l'écran.
    2. Il est détruit quand sa section est loin (ça libère son contexte WebGL).
    3. Il y a un maximum d'effets vivants en même temps : 3 sur téléphone, 6 sur ordinateur.
  Les effets eux-mêmes ne sont pas modifiés.

  Utilisation, dans ComponentFactory.js :

      import LazyGL from './components/LazyGL.js';

      CrystalizedBall: LazyGL(CrystalizedBall),                   // au lieu de  CrystalizedBall,
      GlowCursor: LazyGL(GlowCursor, { skipOnTouch: true }),      // jamais créé sur écran tactile

  Options (2e paramètre, toutes facultatives) :
      skipOnTouch   true = l'effet n'est jamais créé sur écran tactile                       (false)
      mobileDpr     résolution max sur écran tactile, écrite dans data-dpr si absente        (1)
      margin        distance avant l'écran à laquelle l'effet est créé, en % de la hauteur   ('60%')
      keepMargin    distance au-delà de laquelle l'effet est détruit                         ('200%')

  Important : la section qui contient l'effet doit avoir sa propre hauteur en CSS.
  Sinon la page « saute » quand l'effet est créé ou détruit.
*/

// Écran tactile (téléphone, tablette) ?
const coarse = window.matchMedia?.('(pointer: coarse)').matches ?? false;

// Nombre maximum d'effets WebGL vivants en même temps
const MAX_LIVE = coarse ? 3 : 6;

// Les effets actuellement créés
const live = new Set();

// Fait de la place avant de créer un nouvel effet :
// détruit celui qui est loin de l'écran depuis le plus longtemps
function makeRoom() {
  while (live.size >= MAX_LIVE) {
    let oldest = null;
    live.forEach((entry) => {
      if (entry.near) return; // on ne détruit jamais un effet qu'on est en train de regarder
      if (!oldest || entry.lastNear < oldest.lastNear) oldest = entry;
    });
    if (!oldest) return; // tous sont près de l'écran : on n'en détruit aucun
    oldest.unmount();
  }
}

export default function LazyGL(Component, options = {}) {
  const {
    skipOnTouch = false,
    mobileDpr = 1,
    margin = '60%',
    keepMargin = '200%',
  } = options;

  // La classe renvoyée se construit comme n'importe quel composant : new ...(element)
  return class LazyGLInstance {
    constructor(element) {
      this.element = element;
      this.instance = null; // l'effet réel, quand il existe
      this.destroyed = false;

      // Sur téléphone, certains effets (curseur lumineux…) n'ont aucun sens : on ne fait rien
      if (skipOnTouch && coarse) return;

      // Résolution réduite sur écran tactile (si tu ne l'as pas déjà fixée dans le HTML)
      if (coarse && mobileDpr && !element.dataset.dpr)
        element.dataset.dpr = String(mobileDpr);

      // Fiche de cet effet dans la liste des effets vivants
      this.entry = {
        near: false, // la section est-elle près de l'écran ?
        lastNear: 0, // la dernière fois qu'elle l'était
        unmount: () => this.unmount(),
      };

      // Certains effets (LightTunnel en fond…) n'ont aucune taille avant d'être créés :
      // dans ce cas on surveille leur parent (la section), sinon on ne les verrait jamais arriver.
      const target =
        element.getBoundingClientRect().height > 0
          ? element
          : element.parentElement || element;

      // Quand la section approche de l'écran : on crée l'effet
      this.nearObserver = new IntersectionObserver(
        ([e]) => {
          this.entry.near = e.isIntersecting;
          if (e.isIntersecting) {
            this.entry.lastNear = performance.now();
            this.mount();
          }
        },
        { rootMargin: `${margin} 0px` },
      );

      // Quand la section est vraiment loin : on détruit l'effet pour libérer la mémoire
      this.farObserver = new IntersectionObserver(
        ([e]) => {
          if (!e.isIntersecting) this.unmount();
        },
        { rootMargin: `${keepMargin} 0px` },
      );

      this.nearObserver.observe(target);
      this.farObserver.observe(target);
    }

    // Crée l'effet
    mount() {
      if (this.instance || this.destroyed) return;
      makeRoom();
      try {
        this.instance = new Component(this.element);
        live.add(this.entry);
      } catch (err) {
        console.warn('[LazyGL] effet non créé :', err);
        this.instance = null;
      }
    }

    // Détruit l'effet (libère le contexte WebGL)
    unmount() {
      if (!this.instance) return;
      try {
        this.instance.destroy?.();
      } catch (err) {
        console.warn('[LazyGL] erreur à la destruction :', err);
      }
      this.instance = null;
      live.delete(this.entry);
    }

    // Arrêt complet (si un jour tu détruis le composant)
    destroy() {
      this.destroyed = true;
      this.nearObserver?.disconnect();
      this.farObserver?.disconnect();
      this.unmount();
    }
  };
}
