import Preloader from './components/Preloader.js';
import Header from './components/Header.js';
import TextAnim from './components/TextAnim.js';
import Scroller from './components/Scroller.js';
import Video from './components/Video.js';
import BorderGlow from './components/BorderGlow.js';
import FlexCarousel from './components/FlexCarousel.js';
import TiltedCard from './components/TiltedCard.js';
import SpecularButton from './components/SpecularButton.js';
import DepthText from './components/DepthText.js';
import GlowCursor from './components/GlowCursor.js';
import CrystalizedBall from './components/CrystalizedBall.js';
import LaserFlow from './components/LaserFlow.js';
import LightTunnel from './components/LightTunnel.js';
import GlassSurface from './components/GlassSurface.js';
import AnchorLinks from './components/AnchorLinks.js';
import TrueFocus from './components/TrueFocus.js';
import LazyGL from './components/LazyGL.js';
import SkillsPlay from './components/SkillsPlay.js';
import MailLink from './components/MailLink.js';

// INTERRUPTEUR DE TEST
//   true  = GlowCursor, CrystalizedBall et LightTunnel sont limités (créés près de l'écran, max 3 sur téléphone)
//   false = tout redevient EXACTEMENT comme avant (tous les effets créés au chargement)
const LAZY = true;

const lazy = (Component, options) =>
  LAZY ? LazyGL(Component, options) : Component;

export default class ComponentFactory {
  constructor() {
    this.componentList = {
      Preloader,
      Header,
      TextAnim,
      Scroller,
      Video,
      BorderGlow,
      FlexCarousel,
      TiltedCard,
      SpecularButton, // ne PAS envelopper : il partage déjà un seul contexte WebGL entre tous les boutons
      DepthText,
      AnchorLinks,
      TrueFocus,
      GlassSurface,
      SkillsPlay,
      MailLink,

      // Effets WebGL
      GlowCursor: lazy(GlowCursor, { skipOnTouch: true }), // pas de curseur lumineux au doigt
      CrystalizedBall: lazy(CrystalizedBall),
      LaserFlow, // volontairement SANS LazyGL : avec l'enveloppe, le fond laser disparaissait
      LightTunnel: lazy(LightTunnel),
    };
    this.init();
  }
  init() {
    const components = document.querySelectorAll('[data-component]');

    for (let i = 0; i < components.length; i++) {
      const element = components[i];
      const componentName = element.dataset.component;

      if (this.componentList[componentName]) {
        // try/catch : si un composant plante, les suivants démarrent quand même
        try {
          const instance = new this.componentList[componentName](element);
        } catch (err) {
          console.error(`La composante ${componentName} a planté :`, err);
        }
      } else {
        console.log(`La composante ${componentName} n'existe pas`);
      }
    }
  }
}
