// Liens d'ancre (#projets, #top, …) compatibles avec GSAP ScrollSmoother.
//
// Pourquoi : avec ScrollSmoother, le contenu est déplacé par un transform. Le saut natif du navigateur
// vers #id se base sur cette position déjà décalée et dépasse la cible (on finit en bas de page / écran noir).
// Ici on intercepte les clics sur <a href="#id"> et on laisse ScrollSmoother faire le déplacement.
// L'URL ne reçoit pas de #hash, et un rafraîchissement redémarre toujours en haut de la page.
//
// Utilisation (une seule fois dans la page) :
//   <div data-component="AnchorLinks" data-offset="80"></div>
//
// data-offset : espace laissé en haut (px) pour ne pas passer sous le header. Défaut 80.
// Sur une cible : data-anchor-offset="0" pour remplacer l'offset (ex. la section hero).

import { ScrollSmoother } from 'gsap/ScrollSmoother';

export default class AnchorLinks {
  constructor(element) {
    const o = parseFloat(element?.dataset?.offset);
    this.offset = Number.isFinite(o) ? o : 80;

    this.onClick = (e) => {
      if (
        e.defaultPrevented ||
        e.button > 0 ||
        e.metaKey ||
        e.ctrlKey ||
        e.shiftKey ||
        e.altKey
      )
        return;
      const a = e.target.closest?.('a[href*="#"]');
      if (
        !a ||
        (a.target && a.target !== '_self') ||
        a.hasAttribute('download')
      )
        return;

      const url = new URL(a.getAttribute('href'), window.location.href);
      // Seulement les ancres de CETTE page
      if (
        url.origin !== window.location.origin ||
        url.pathname !== window.location.pathname
      )
        return;
      const hash = url.hash;
      if (!hash || hash === '#') return; // href="#" : on laisse les autres composants (vidéo, etc.)

      // On n'écrit PAS le #hash dans l'URL : sinon un rafraîchissement ramènerait à cette section
      if (this.goTo(hash, true)) e.preventDefault();
    };

    document.addEventListener('click', this.onClick);

    // Rafraîchir la page = repartir en haut (pas de restauration du scroll, pas de #hash dans l'URL)
    if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
    if (window.location.hash) {
      history.replaceState(
        null,
        '',
        window.location.pathname + window.location.search,
      );
    }
    const toTop = () => {
      window.scrollTo(0, 0);
      ScrollSmoother.get()?.scrollTo(0, false);
    };
    toTop();
    this.initTimer = setTimeout(toTop, 300);
  }

  goTo(hash, smooth = true) {
    const id = decodeURIComponent(hash.replace(/^#/, ''));
    const smoother = ScrollSmoother.get();
    const isTop = id === '' || id === 'top';
    const el = isTop ? null : document.getElementById(id);
    if (!isTop && !el) return false;

    if (smoother) {
      if (isTop) {
        smoother.scrollTo(0, smooth);
      } else {
        const own = parseFloat(el.dataset.anchorOffset);
        const offset = Number.isFinite(own) ? own : this.offset;
        smoother.scrollTo(el, smooth, `top ${offset}px`);
      }
    } else if (isTop) {
      window.scrollTo({ top: 0, behavior: smooth ? 'smooth' : 'auto' });
    } else {
      const own = parseFloat(el.dataset.anchorOffset);
      const offset = Number.isFinite(own) ? own : this.offset;
      const y = el.getBoundingClientRect().top + window.scrollY - offset;
      window.scrollTo({ top: y, behavior: smooth ? 'smooth' : 'auto' });
    }
    return true;
  }

  destroy() {
    clearTimeout(this.initTimer);
    document.removeEventListener('click', this.onClick);
  }
}
