// Chef d'orchestre de la performance : mesure la fluidité réelle de la page et ajuste la résolution
// des effets WebGL (laser, tunnel, boule, curseur, carrousel).
//   - Ordinateur puissant (RTX, etc.) : l'échelle reste à 1, donc AUCUNE différence visuelle.
//   - Machine qui peine (GPU intégré, téléphone) : la résolution baisse par petits paliers jusqu'à ce que ça redevienne fluide,
//     puis remonte seulement si la machine a de la marge.
// Réglages dans l'adresse du site (pour tester) :  ?quality=high  (jamais de baisse)   ?quality=low  (toujours doux)
//   ?debug  affiche les changements dans la console.
//
// Utilisation dans un effet :  import Perf from './Perf.js';
//   résolution = résolutionNormale * Perf.scale;      et      const stop = Perf.onChange(resize);  (stop() dans destroy)

const coarse = window.matchMedia?.('(pointer: coarse)').matches ?? false;
const params = new URLSearchParams(location.search);
const forced = params.get('quality');
const debug = params.has('debug');

const MIN_SCALE = coarse ? 0.5 : 0.55;
const START_SCALE = forced === 'low' ? MIN_SCALE : coarse ? 0.85 : 1;
const SLOW_MS = 22; // médiane au-dessus = moins de ~45 images/s : on baisse
const FAST_MS = 17.5; // médiane en dessous = ~60 images/s ou plus : on peut remonter
const WINDOW = 45; // nombre d'images mesurées avant chaque décision
const WARMUP_MS = 5000; // on ignore le chargement (preloader, compilation des shaders)

let scale = START_SCALE;
const listeners = new Set();
let cooldownUntil = 0;
let backoff = 20000;
let lastDownAt = 0;
let fastWindows = 0;

const notify = () => {
  if (debug) console.info(`[Perf] échelle de résolution : ${scale.toFixed(2)}`);
  listeners.forEach((fn) => {
    try {
      fn();
    } catch (err) {
      console.error('[Perf]', err);
    }
  });
};

const setScale = (next) => {
  next = Math.min(1, Math.max(MIN_SCALE, next));
  if (Math.abs(next - scale) < 0.01) return;
  scale = next;
  notify();
};

const decide = (median, now) => {
  if (median > SLOW_MS && scale > MIN_SCALE) {
    // Si on vient de remonter et que ça re-lague, on attend plus longtemps avant de réessayer
    if (now - lastDownAt < 15000) backoff = Math.min(backoff * 2, 120000);
    lastDownAt = now;
    cooldownUntil = now + backoff;
    fastWindows = 0;
    setScale(scale * 0.85);
    return;
  }
  if (median < FAST_MS && scale < 1 && now > cooldownUntil) {
    fastWindows++;
    if (fastWindows >= 4) {
      fastWindows = 0;
      setScale(scale / 0.92);
    }
  } else {
    fastWindows = 0;
  }
};

const monitor = () => {
  const times = [];
  let last = 0;
  const startedAt = performance.now();

  const tick = (now) => {
    requestAnimationFrame(tick);
    if (document.hidden) {
      last = 0;
      times.length = 0;
      return;
    }
    if (last) {
      const dt = now - last;
      // les très longues pauses (onglet en arrière-plan, défilement bloqué) ne comptent pas
      if (dt < 250) times.push(dt);
    }
    last = now;
    if (times.length >= WINDOW) {
      const sorted = [...times].sort((a, b) => a - b);
      const median = sorted[sorted.length >> 1];
      times.length = 0;
      if (now - startedAt > WARMUP_MS) decide(median, now);
    }
  };
  requestAnimationFrame(tick);
};

if (forced !== 'high' && forced !== 'low') monitor();

const Perf = {
  coarse,
  get scale() {
    return forced === 'high' ? 1 : scale;
  },
  // Appelle fn quand l'échelle change. Renvoie une fonction pour se désabonner.
  onChange(fn) {
    listeners.add(fn);
    return () => listeners.delete(fn);
  },
};

if (debug) window.__perf = Perf;

export default Perf;
