// Interactivité des compétences : les softskills et les logiciels se laissent bousculer.
//   - Souris : le curseur repousse les éléments proches (ils reviennent en rebondissant).
//   - Souris : on peut aussi attraper un élément, le déplacer et le lancer (il bouscule ses voisins).
//   - Tactile : un tap fait « sauter » l'élément et écarte ses voisins (le défilement de la page n'est jamais bloqué).
// Usage : <div class="skills" data-component="SkillsPlay"> ... <ul><li>...</li></ul> ... </div>
// Réglages (optionnels) : data-radius="50" (rayon de répulsion, px), data-push="1" (force), data-drag="true"
// Animations (le CSS est dans about.scss) :
//   - Cascade : à l'arrivée à l'écran, les éléments apparaissent un à un (classe .is-in, variable --i sur chaque <li>).
//   - Flottement : les icônes de logiciels flottent doucement tant que la carte est visible (classe .is-visible).
//   - Survol : l'élément sous le curseur (ou tapé au doigt) reçoit .is-hot / .is-tip : lueur + nom du logiciel (data-label).
// Rien ne tourne quand tout est au repos ou hors écran.

const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
const num = (v, fallback) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : fallback;
};

const STIFFNESS = 140; // force du ressort de rappel
const DAMPING = 15; // frottement (plus haut = moins de rebonds)
const MAX_OFFSET = 22; // un élément ne s'éloigne jamais de plus que ça de sa place

export default class SkillsPlay {
  constructor(element) {
    this.root = element;
    const d = element.dataset;
    this.radius = clamp(num(d.radius, 50), 40, 300);
    this.push = clamp(num(d.push, 1), 0, 4);
    this.dragEnabled = d.drag !== 'false';

    this.reduced = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (this.reduced) return; // pas d'animation pour ceux qui l'ont désactivée

    this.items = [...element.querySelectorAll('li')].map((el) => ({
      el,
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      rx: 0, // centre au repos (écran), mis à jour à chaque image
      ry: 0,
      rw: 0,
      rh: 0,
    }));
    if (!this.items.length) return;

    // --i : rang de chaque élément (délai de la cascade et décalage du flottement)
    this.items.forEach((it, i) => it.el.style.setProperty('--i', i));
    element.classList.add('is-ready'); // cache les éléments jusqu'à leur arrivée à l'écran (sans JS, tout reste visible)

    this.pointer = { x: 0, y: 0, inside: false, t: 0 };
    this.grab = null; // { item, dx, dy, lastX, lastY, lastT }
    this.raf = 0;
    this.visible = true;
    this.last = 0;

    this.items.forEach((it) => {
      Object.assign(it.el.style, {
        willChange: 'transform',
        userSelect: 'none',
        webkitUserSelect: 'none',
        touchAction: 'pan-y', // le doigt peut toujours faire défiler la page
        cursor: this.dragEnabled ? 'grab' : 'default',
      });
    });

    this.onMove = this.onMove.bind(this);
    this.onLeave = this.onLeave.bind(this);
    this.onDown = this.onDown.bind(this);
    this.onUp = this.onUp.bind(this);
    this.tick = this.tick.bind(this);

    element.addEventListener('pointermove', this.onMove);
    element.addEventListener('pointerleave', this.onLeave);
    element.addEventListener('pointerdown', this.onDown);
    window.addEventListener('pointerup', this.onUp);
    window.addEventListener('pointercancel', this.onUp);

    this.io = new IntersectionObserver(
      ([entry]) => {
        this.visible = entry.isIntersecting;
        element.classList.toggle('is-visible', this.visible); // le flottement ne tourne que si la carte est à l'écran
        // La cascade ne joue qu'une fois, quand une bonne partie de la carte est visible
        if (entry.isIntersecting && entry.intersectionRatio >= 0.15) {
          element.classList.add('is-in');
        }
        if (!this.visible) this.stop();
        else this.start();
      },
      { threshold: [0, 0.15, 0.4] },
    );
    this.io.observe(element);
  }

  /* ---------- Entrées ---------- */

  onMove(e) {
    this.pointer.x = e.clientX;
    this.pointer.y = e.clientY;
    this.pointer.t = performance.now();
    // Le doigt ne repousse pas : seul un tap agit (voir onDown)
    this.pointer.inside = e.pointerType === 'mouse' || e.pointerType === 'pen';
    this.start();
  }

  onLeave() {
    this.pointer.inside = false;
    this.start();
  }

  onDown(e) {
    const hit = this.items.find((it) => it.el.contains(e.target));
    if (e.pointerType === 'touch') {
      // Tap : l'élément saute, ses voisins s'écartent
      if (hit) this.pop(hit);
      return;
    }
    if (!hit || !this.dragEnabled || e.button > 0) return;
    this.measure();
    this.grab = {
      item: hit,
      dx: e.clientX - (hit.rx + hit.x),
      dy: e.clientY - (hit.ry + hit.y),
      lastX: e.clientX,
      lastY: e.clientY,
      lastT: performance.now(),
    };
    hit.vx = hit.vy = 0;
    hit.el.style.cursor = 'grabbing';
    hit.el.style.zIndex = '5';
    this.pointer.x = e.clientX;
    this.pointer.y = e.clientY;
    this.pointer.inside = true;
    this.pointer.t = performance.now();
    e.preventDefault(); // pas de sélection de texte ni de glisser-déposer
    this.start();
  }

  onUp() {
    if (!this.grab) return;
    const { item } = this.grab;
    item.el.style.cursor = 'grab';
    item.el.style.zIndex = '';
    this.grab = null;
    this.start();
  }

  pop(item) {
    this.measure();
    // Au doigt, il n'y a pas de survol : on montre le nom du logiciel pendant un instant
    this.items.forEach((o) => o.el.classList.remove('is-tip'));
    item.el.classList.add('is-tip');
    clearTimeout(this.tipTimer);
    this.tipTimer = setTimeout(() => item.el.classList.remove('is-tip'), 1800);
    item.vy -= 70; // petit saut
    for (const o of this.items) {
      if (o === item) continue;
      const dx = o.rx + o.x - (item.rx + item.x);
      const dy = o.ry + o.y - (item.ry + item.y);
      const dist = Math.hypot(dx, dy) || 1;
      if (dist < this.radius * 1.6) {
        const k = (1 - dist / (this.radius * 1.6)) * 90 * this.push;
        o.vx += (dx / dist) * k;
        o.vy += (dy / dist) * k;
      }
    }
    this.start();
  }

  /* ---------- Boucle ---------- */

  start() {
    if (this.raf || !this.visible) return;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.tick);
  }

  stop() {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  // Position au repos de chaque élément (sans notre décalage), en coordonnées écran
  measure() {
    for (const it of this.items) {
      const r = it.el.getBoundingClientRect();
      it.rx = r.left + r.width / 2 - it.x;
      it.ry = r.top + r.height / 2 - it.y;
      it.rw = r.width;
      it.rh = r.height;
    }
  }

  tick(now) {
    const dt = Math.min((now - this.last) / 1000, 1 / 30);
    this.last = now;
    this.measure();

    const grabbed = this.grab?.item || null;

    // Élément « touché » par la souris : sa place d'origine OU sa position actuelle contient le curseur
    // (il est repoussé par le curseur, donc on garde la lueur même s'il s'est un peu écarté)
    for (const it of this.items) {
      const px = this.pointer.x;
      const py = this.pointer.y;
      const inRect = (cx, cy) =>
        Math.abs(px - cx) <= it.rw / 2 && Math.abs(py - cy) <= it.rh / 2;
      const hot =
        this.pointer.inside &&
        (inRect(it.rx, it.ry) || inRect(it.rx + it.x, it.ry + it.y));
      if (hot !== it.hot) {
        it.hot = hot;
        it.el.classList.toggle('is-hot', hot);
      }
    }

    // Le pointeur suit l'élément attrapé
    if (grabbed) {
      const g = this.grab;
      const tx = this.pointer.x - g.dx - grabbed.rx;
      const ty = this.pointer.y - g.dy - grabbed.ry;
      const nx = clamp(tx, -MAX_OFFSET * 1.3, MAX_OFFSET * 1.3);
      const ny = clamp(ty, -MAX_OFFSET * 1.3, MAX_OFFSET * 1.3);
      // vitesse de lancer lissée (pour le relâchement)
      grabbed.vx = (nx - grabbed.x) / Math.max(dt, 0.001);
      grabbed.vy = (ny - grabbed.y) / Math.max(dt, 0.001);
      grabbed.vx = clamp(grabbed.vx, -400, 400);
      grabbed.vy = clamp(grabbed.vy, -400, 400);
      grabbed.x = nx;
      grabbed.y = ny;
      g.lastT = now;
    }

    let moving = false;
    for (const it of this.items) {
      if (it === grabbed) {
        moving = true;
        this.apply(it, true);
        continue;
      }
      let ax = -STIFFNESS * it.x - DAMPING * it.vx;
      let ay = -STIFFNESS * it.y - DAMPING * it.vy;

      const cx = it.rx + it.x;
      const cy = it.ry + it.y;

      // Répulsion du curseur (souris seulement) : la distance se mesure jusqu'au BORD de l'élément (pas son centre),
      // donc un grand chip réagit aussi bien qu'une petite icône
      if (this.pointer.inside && !grabbed) {
        const dx = cx - this.pointer.x;
        const dy = cy - this.pointer.y;
        const ex = Math.max(Math.abs(dx) - it.rw / 2, 0);
        const ey = Math.max(Math.abs(dy) - it.rh / 2, 0);
        const dist = Math.hypot(ex, ey);
        if (dist < this.radius) {
          const len = Math.hypot(dx, dy) || 1;
          const f = (1 - dist / this.radius) ** 2 * 1200 * this.push;
          ax += (dx / len) * f;
          ay += (dy / len) * f;
        }
      }

      // Les éléments se tassent entre eux : quand deux rectangles se chevauchent, ils se repoussent
      // (l'élément attrapé compte aussi, donc on peut pousser les autres devant soi)
      for (const o of this.items) {
        if (o === it) continue;
        const dx = cx - (o.rx + o.x);
        const dy = cy - (o.ry + o.y);
        const ox = (it.rw + o.rw) / 2 + 6 - Math.abs(dx);
        const oy = (it.rh + o.rh) / 2 + 6 - Math.abs(dy);
        if (ox > 0 && oy > 0) {
          // on sépare selon l'axe où le chevauchement est le plus petit
          if (ox < oy) ax += Math.sign(dx || 1) * ox * 70 * this.push;
          else ay += Math.sign(dy || 1) * oy * 70 * this.push;
        }
      }

      it.vx += ax * dt;
      it.vy += ay * dt;
      it.x = clamp(it.x + it.vx * dt, -MAX_OFFSET, MAX_OFFSET);
      it.y = clamp(it.y + it.vy * dt, -MAX_OFFSET, MAX_OFFSET);

      const still =
        Math.abs(it.x) < 0.05 &&
        Math.abs(it.y) < 0.05 &&
        Math.abs(it.vx) < 0.5 &&
        Math.abs(it.vy) < 0.5;
      if (still) {
        it.x = it.y = it.vx = it.vy = 0;
        if (it.el.style.transform) it.el.style.transform = '';
      } else {
        moving = true;
        this.apply(it, false);
      }
    }

    // On continue tant que ça bouge, ou que la souris vient de bouger sur la zone
    const recent = this.pointer.inside && now - this.pointer.t < 800;
    if (this.visible && (moving || recent || this.grab)) {
      this.raf = requestAnimationFrame(this.tick);
    } else {
      this.raf = 0;
    }
  }

  apply(it, held) {
    // Léger penchement selon la vitesse, et un petit grossissement quand on le tient
    const tilt = clamp(it.vx * 0.0015, -1.5, 1.5);
    const scale = held ? 1.02 : 1;
    it.el.style.transform = `translate3d(${it.x.toFixed(2)}px, ${it.y.toFixed(2)}px, 0) rotate(${tilt.toFixed(2)}deg) scale(${scale})`;
  }

  destroy() {
    this.stop();
    this.io?.disconnect();
    this.root.removeEventListener('pointermove', this.onMove);
    this.root.removeEventListener('pointerleave', this.onLeave);
    this.root.removeEventListener('pointerdown', this.onDown);
    window.removeEventListener('pointerup', this.onUp);
    window.removeEventListener('pointercancel', this.onUp);
    clearTimeout(this.tipTimer);
    this.root.classList.remove('is-ready', 'is-in', 'is-visible');
    this.items?.forEach((it) => {
      it.el.style.transform = '';
      it.el.classList.remove('is-hot', 'is-tip');
    });
  }
}
