// Port vanilla JS de React Bits <DepthText /> : aucun package à installer.
// Usage : <h1 data-component="DepthText" data-face-color="#A855F7">PORTFOLIO</h1>
// Dégradé sur la face avant : data-gradient-from="#ffb3ff" data-gradient-to="#a855f7" (data-gradient-angle="180").
// Il est fait avec 2 faces superposées dans la scène 3D (la 2e est masquée en dégradé), donc il bouge avec le reste.
// La taille, la police et le poids viennent de ton CSS (font-size, font-weight, etc.).

const MAX_LAYERS = 64;
const clamp = (value, min, max) => Math.min(Math.max(value, min), max);
const num = (v, fallback) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : fallback;
};
const bool = (v, fallback) => (v === undefined ? fallback : v !== 'false');

const layerColor = (faceColor, depthColor, index, total) => {
  const progress = total <= 1 ? 1 : index / total;
  const eased = progress * progress;
  const faceMix = Math.round((1 - eased) * 72 + 4);
  return `color-mix(in srgb, ${faceColor} ${faceMix}%, ${depthColor})`;
};

const rotation = (x, y) =>
  `rotateX(${x.toFixed(3)}deg) rotateY(${y.toFixed(3)}deg)`;

export default class DepthText {
  constructor(element) {
    this.root = element;
    const d = element.dataset;

    this.text = d.text || element.textContent.trim();
    this.layers = clamp(Math.round(num(d.layers, 34)), 2, MAX_LAYERS);
    this.depth = clamp(num(d.depth, 2.4), 0, 12);
    // Écran tactile : moitié moins de couches (chacune est une grosse texture GPU), espacées 2x plus pour garder la même profondeur
    if (window.matchMedia('(pointer: coarse)').matches && this.layers > 16) {
      const fewer = Math.round(this.layers / 2);
      this.depth = clamp((this.depth * this.layers) / fewer, 0, 12);
      this.layers = fewer;
    }
    this.faceColor = d.faceColor || '#f8fafc';
    this.depthColor = d.depthColor || '#7c3aed';
    this.tilt = clamp(num(d.tilt, 7.5), 0, 12);
    this.pointerTracking = bool(d.pointerTracking, true);
    this.smoothing = clamp(num(d.smoothing, 0.14), 0.02, 0.35);
    this.perspective = clamp(num(d.perspective, 900), 300, 2000);
    this.autoOrbit = bool(d.autoOrbit, true);
    this.orbitSpeed = clamp(num(d.orbitSpeed, 0.35), 0, 2);
    this.shadow = bool(d.shadow, true);

    // Dégradé sur la face avant : 2 faces superposées, la 2e masquée en dégradé
    this.gradientFrom = d.gradientFrom || '';
    this.gradientTo = d.gradientTo || '';
    this.gradientAngle = num(d.gradientAngle, 180);
    this.gradientStart = num(d.gradientStart, 10); // où commence la 2e couleur, en %
    this.gradientEnd = num(d.gradientEnd, 90); // où elle est complète, en %
    this.hasGradient = Boolean(this.gradientFrom && this.gradientTo);
    if (this.hasGradient) this.faceColor = this.gradientFrom;

    this.base = { x: -this.tilt * 0.32, y: this.tilt * 0.42 };

    this.build();

    this.reduced = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    const finePointer = window.matchMedia(
      '(hover: hover) and (pointer: fine)',
    ).matches;
    this.canTrack = this.pointerTracking && finePointer && !this.reduced;

    this.current = { ...this.base };
    this.target = { ...this.base };
    this.activePointer = false;
    this.visible = true;
    this.raf = 0;
    this.startTime = performance.now();

    this.stage.style.transform = rotation(this.base.x, this.base.y);
    if (this.reduced) return;

    this.onMove = this.onMove.bind(this);
    this.onLeave = this.onLeave.bind(this);
    this.tick = this.tick.bind(this);

    if (this.canTrack) {
      window.addEventListener('pointermove', this.onMove, { passive: true });
      document.documentElement.addEventListener('pointerleave', this.onLeave);
      window.addEventListener('blur', this.onLeave);
    }

    this.io = new IntersectionObserver(([entry]) => {
      this.visible = entry.isIntersecting;
      if (this.visible) this.start();
    });
    this.io.observe(this.root);

    this.start();
  }

  build() {
    const root = this.root;
    root.setAttribute('aria-label', this.text);
    root.textContent = '';
    root.classList.add('depth-text');

    root.style.setProperty('--depth-text-perspective', `${this.perspective}px`);
    root.style.setProperty('--depth-text-face-color', this.faceColor);
    root.style.setProperty('--depth-text-depth-color', this.depthColor);
    root.style.setProperty(
      '--depth-text-shadow',
      this.shadow
        ? `0 22px 34px color-mix(in srgb, ${this.depthColor} 36%, transparent), 0 4px 8px rgba(0, 0, 0, 0.28)`
        : 'none',
    );

    this.stage = document.createElement('span');
    this.stage.className = 'depth-text__stage';
    this.stage.setAttribute('aria-hidden', 'true');

    for (let i = 0; i < this.layers; i++) {
      const index = this.layers - i;
      const layer = document.createElement('span');
      layer.className = 'depth-text__layer';
      layer.textContent = this.text;
      layer.style.color = layerColor(
        this.faceColor,
        this.depthColor,
        index,
        this.layers,
      );
      layer.style.transform = `translateZ(${-index * this.depth}px)`;
      this.stage.appendChild(layer);
    }

    const face = document.createElement('span');
    face.className = 'depth-text__face';
    face.textContent = this.text;
    this.stage.appendChild(face);

    if (this.hasGradient) {
      // 2e face, même position, masquée en dégradé : elle fond vers la 2e couleur
      const overlay = document.createElement('span');
      overlay.className = 'depth-text__face depth-text__face--overlay';
      overlay.textContent = this.text;
      overlay.style.color = this.gradientTo;
      const mask = `linear-gradient(${this.gradientAngle}deg, transparent ${this.gradientStart}%, #000 ${this.gradientEnd}%)`;
      overlay.style.webkitMaskImage = mask;
      overlay.style.maskImage = mask;
      this.stage.appendChild(overlay);
    }
    root.appendChild(this.stage);
  }

  onMove(e) {
    const rect = this.root.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    this.activePointer = true;
    const x = clamp(
      (e.clientX - (rect.left + rect.width / 2)) / (rect.width * 0.8),
      -1,
      1,
    );
    const y = clamp(
      (e.clientY - (rect.top + rect.height / 2)) / (rect.height * 0.8),
      -1,
      1,
    );
    this.target.x = this.base.x - y * this.tilt;
    this.target.y = this.base.y + x * this.tilt;
  }

  onLeave() {
    this.activePointer = false;
    this.target.x = this.base.x;
    this.target.y = this.base.y;
  }

  start() {
    if (this.raf || !this.visible) return;
    this.raf = requestAnimationFrame(this.tick);
  }

  tick(now) {
    if (!this.visible) {
      this.raf = 0;
      return;
    }

    if ((!this.canTrack || !this.activePointer) && this.autoOrbit) {
      const elapsed = (now - this.startTime) / 1000;
      const orbit = elapsed * this.orbitSpeed * Math.PI * 2;
      const amount = this.canTrack ? 0.18 : 0.55;
      this.target.x = this.base.x + Math.sin(orbit) * this.tilt * amount;
      this.target.y = this.base.y + Math.cos(orbit * 0.85) * this.tilt * amount;
    }

    this.current.x += (this.target.x - this.current.x) * this.smoothing;
    this.current.y += (this.target.y - this.current.y) * this.smoothing;
    this.stage.style.transform = rotation(this.current.x, this.current.y);

    this.raf = requestAnimationFrame(this.tick);
  }

  destroy() {
    cancelAnimationFrame(this.raf);
    window.removeEventListener('pointermove', this.onMove);
    document.documentElement.removeEventListener('pointerleave', this.onLeave);
    window.removeEventListener('blur', this.onLeave);
    this.io?.disconnect();
  }
}
